WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, SUBSTRING(promo_code, 1, 4) AS promo_code_prefix FROM promotions WHERE starts_on >= TO_DATE('2023-12-23') AND channel IS NOT NULL) SELECT CASE WHEN discount_pct >= 0.3 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, DATE_TRUNC('YEAR', ends_on) AS year_start, SIZE(COLLECT_SET(channel)) AS num_channels, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, SUM(CASE WHEN promo_code = 'SPRING10' THEN discount_pct ELSE 0 END) AS spring10_discount_pct, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, MAX(discount_pct) AS max_discount_pct, SIZE(COLLECT_SET(channel)) AS num_channels_2 FROM base GROUP BY GROUPING SETS ((CASE WHEN discount_pct >= 0.3 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', ends_on)), (CASE WHEN discount_pct >= 0.3 THEN 'PREMIUM' ELSE 'STANDARD' END));
